package com.hms.queue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.hms.appointments.*; import com.hms.doctors.*; import com.hms.tenancy.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class QueueBoardControllerTests { @Autowired MockMvc mockMvc; @Autowired TenantRepository tenants; @Autowired DoctorRepository doctors; @Autowired AppointmentRepository appointments; @Autowired QueueTokenRepository tokens; @BeforeEach void setup(){tokens.deleteAll();appointments.deleteAll();doctors.deleteAll();tenants.deleteAll();Tenant tenant=tenants.save(new Tenant(UUID.randomUUID(),"queue-care","Queue Care",null,TenantStatus.ACTIVE,null,null));doctors.save(new Doctor(tenant.getId(),new CreateDoctorRequest("Dr. Queue","General",null,null,3,null,null,true,Set.of())));} @Test void rejectsUnknownTenantQueueBoard() throws Exception {mockMvc.perform(get("/api/hospitals/unknown/queue-board").param("date","2026-09-28")).andExpect(status().isNotFound());} @Test void returnsEmptyBoardForValidTenant() throws Exception {mockMvc.perform(get("/api/hospitals/queue-care/queue-board").param("date","2026-09-28")).andExpect(status().isOk()).andExpect(jsonPath("$.date").value("2026-09-28")).andExpect(jsonPath("$.tokens").isEmpty());}}
